@startuml

class Animal {
  + ID : long
  + name : string
}

class Owner {
  + ID : long
  + name : string
  + address : string
  + phone : string
}

class Breed {
  + name : string
}

class Physician {
  + ID : long
  + name : string
  + address : string
  + phone : string
}

class Appointment {
  + date : date
  + time : time
}

class MedicalCondition {
  + commonName : string
  + scientificName : string
}

"0..1" -- "1" Animal : belongs to
"1" -- "0..1" Animal : owner
"1" -- "*" Appointment : attends
"1" -- "1" Appointment : responsible physician
"1" -- "*" Appointment : attended by
"1" -- "*" Appointment : detects
"1" -- "*" MedicalCondition : detected in
"1" -- "*" Breed : common to

@enduml

